      "contributions": [
        "Motivates generalized BCE with multiple negatives to address sampled-BCE overconfidence."
      ],
      "limitations": [
        "Additional negatives increase computation and do not explicitly address stale preferences."
      ]
    },
    {
      "title": "R²NS",
      "link": "https://renzhaochun.github.io/assets/pdf/WWW_2026_Camera_Ready.pdf",
      "contributions": [
